 err:[{s:'If I will see her, I will tell her.',fix:'If I see her, I will tell her.',fa:'بعد از if حال ساده.'},{s:'We will start when everybody will be ready.',fix:'We will start when everybody is ready.',fa:'بعد از when حال ساده.'}],
