 err:[{s:'The window was break by the wind.',fix:'The window was broken by the wind.',fa:'قسمت سوم break = broken.'},{s:'Many houses were destroy in the earthquake.',fix:'Many houses were destroyed in the earthquake.',fa:'ed لازم است.'}],
